// ROLE_VECTORS_END
// Must match generated public_vectors.json and role_vectors.json in castle-wall-daemon/src/business_profile, checked by the generator.
describe("strict cross-language profile",()=>{
 it.each(PUBLIC_VECTORS)("$name",row=>{
  const key=Buffer.from(row.public_key,"hex"),signature=Buffer.from(row.signature,"hex"),message=Buffer.from(row.message,"hex");
  expect(strictEncodingProfile(signature,key)).toBe(row.valid);
  expect(strictVerify(message,signature,key)).toBe(row.valid);
  if("point_kind" in row)expect(isStrictEd25519PointEncoding(row.point_kind==="A"?key:signature.subarray(0,32))).toBe(false);
 });
 it.each(ROLE_VECTORS)("role vector $role",row=>{
  const bytes=Buffer.from(row.preimage,"hex");const body=JSON.parse(bytes.toString());
  const public_key=Buffer.from(row.public_key,"hex").toString("base64url");
  expect(roleKid(row.role as SigningRole,1,public_key)).toBe(row.kid);
  expect(verifyRecord(bytes,Buffer.from(row.signature,"hex").toString("base64url"),{role:row.role as SigningRole,epoch:1,kid:row.kid,public_key,identity_id:body.identity_id,machine_id:body.machine_id},z.object({count:safeInteger}).strict(), roleEntry(row.role).record_kinds[0])).toBe(true);
 });
 it("rejects noncanonical base64url pad bits",()=>{
  const canonical=Buffer.from(PUBLIC_VECTORS[0].public_key,"hex").toString("base64url");
  const alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
  const changed=canonical.slice(0,-1)+alphabet[alphabet.indexOf(canonical.at(-1)!)+1];
  expect(Buffer.from(changed,"base64url")).toEqual(Buffer.from(canonical,"base64url"));
  expect(()=>decodeCanonical(changed,32)).toThrow("K1_REFUSED");
 });
 it("covers the whole role registry",()=>{expect(ROLE_VECTORS.map(row=>row.role).sort()).toEqual(ROLE_REGISTRY.map(row=>row.role).sort());});
});
